// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= address(this).balance);
        Reverter reverter = new Reverter();
        vm.deal(address(this), amount);
        uint256 beforeCount = c.depositsCount();
        bool ok = true;
        try c.sendMoney(address(reverter), amount, data) {
        } catch {
            ok = false;
        }
        uint256 afterCount = c.depositsCount();
        assertTrue((!ok && afterCount == beforeCount) || (ok && afterCount == beforeCount + 1));
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
